const london = { timeZone: "Europe/London", hour: "2-digit", minute: "2-digit" };
const first = new Date("2024-10-27T00:30:00Z");
const second = new Date("2024-10-27T01:30:00Z");

console.log(first.toLocaleTimeString("en-GB", london));
console.log(second.toLocaleTimeString("en-GB", london));
console.log(new Date("2024-10-27T02:30:00+02:00").getTime() === first.getTime());

const day = new Date(2024, 9, 27);
const result = day.setDate(32);
console.log(typeof result, day.getMonth(), day.getDate());
console.log(new Date("2024-10-27").getUTCHours());
